"""Simulator settings agreed in the design doc.

All amounts are in USD unless the name says otherwise. Change the numbers here,
not in the engines, so every engine and the app use the same values.
"""

from datetime import date

BASE_CCY = "USD"
CURRENCIES = ["USD", "EUR", "GBP", "CHF"]

# History generated by the daily engine (backfill start).
HISTORY_START = date(2025, 1, 1)

# Daily cash management
LOOKAHEAD_BUSINESS_DAYS = 5
OPERATING_MIN_USD = 100_000          # cash left on TRS bank accounts per currency
FX_TOLERANCE_USD = 50_000            # net open position allowed per currency
IV_BUFFER_USD = 50_000_000           # minimum IV deposit with TRS

# Intercompany pricing (arm's length), as a margin on the MMF rate of the currency
IC_LOAN_MARGIN_BP = 50               # TRS lends: MMF rate + 50 bp
IC_DEPOSIT_MARGIN_BP = -10           # TRS borrows: MMF rate - 10 bp

# Facility drawing tenors (calendar months); 0 = short bridge in days
BRIDGE_MAX_DAYS = 10
TENOR_IF_DISTRIBUTION_WITHIN_3M = 1
TENOR_LONGER_NEED = 3

# Day-count basis per currency (actual/360 or actual/365)
DAY_COUNT_BASIS = {"USD": 360, "EUR": 360, "CHF": 360, "GBP": 365}

# MMF interest is paid on this business day of the following month
MMF_INTEREST_PAY_BD = 2

# Tiers shown as badges in the app
TIERS = {
    1: "I know this",
    2: "Easy to argue",
    3: "I know the definition",
    4: "Good to know it exists",
}

# ---------------------------------------------------------------
# Phase 2: daily engine
# ---------------------------------------------------------------
# MMF yield = overnight rate (SOFR, ESTR, SONIA, SARON) + this spread
MMF_SPREAD_BP = -5
OVERNIGHT_INDEX = {"USD": "SOFR", "EUR": "ESTR", "GBP": "SONIA", "CHF": "SARON"}

# Where TRS invests surplus cash in each currency (no CHF MMF: CHF call deposit)
INVESTMENT_ACCOUNT = {"USD": "MMF-USD-A", "EUR": "MMF-EUR-A", "GBP": "MMF-GBP-A", "CHF": "TRS-BKA-CHF-DEP"}
TRS_MAIN_ACCOUNT = {c: f"TRS-BKA-{c}" for c in CURRENCIES}

# Small, reproducible variation on scheduled flows: max +/- share of the amount
FLOW_VARIATION = {"MGMT_FEE": 0.05, "ADMIN_FEE": 0.05, "PAYROLL": 0.02, "SUPPLIER": 0.05}
# Some supplier payments go out a few business days late
LATE_PAYMENT = {"SUPPLIER": {"probability": 0.2, "max_days": 5}}

# Opening position on HISTORY_START (clean start), in each currency
TRS_EQUITY_USD = 20_000_000
OPENING_IV_DEPOSIT_USD = 80_000_000
# Service companies' cash already held with TRS on their IC current accounts
OPENING_IC_CURRENT_ACCOUNTS = {("MGT", "GBP"): 10_000_000, ("US", "USD"): 5_000_000,
                               ("CH", "CHF"): 3_000_000, ("EU", "EUR"): 5_000_000}
# Only move cash in or out of the MMF when the change is at least this much (USD equivalent)
MIN_INVESTMENT_TRADE_USD = 25_000

# ---------------------------------------------------------------
# Phase 3: daily cash management (the autopilot, src/tsim/autopilot.py)
# ---------------------------------------------------------------
# IC term deposits. Each service company keeps its OPEX on call: a floor of about a month of
# scheduled outflows (plus a small buffer), on top of whatever its projected balance needs until the
# deposit matures (fees come in quarterly, costs go out monthly). The rest goes into 3-month fixed
# deposits, placed on the first business day of each month and at each maturity (a ladder).
IC_WORKING_BALANCE_MONTHS = 1
IC_WORKING_BALANCE_BUFFER = 0.10     # floor = next month's outflows x 1.10
IC_DEPOSIT_TENOR_MONTHS = 3
IC_TERM_PREMIUM_BP = 5               # fixed rate = IC deposit rate on the start date + 5 bp
MIN_IC_DEPOSIT_USD = 1_000_000       # smaller surpluses stay on call (USD equivalent)
IC_DEPOSIT_ROUNDING = 100_000        # term deposits in round amounts (currency units)

# FX. Service companies convert their foreign-currency IC balances into their own currency on the
# last joint business day of the month. They book the known amounts as internal forwards with TRS
# a few business days ahead; TRS nets them and covers the net with one external forward per currency.
FX_HEDGE_LOOKAHEAD_BD = LOOKAHEAD_BUSINESS_DAYS
SPOT_DAYS = 2                        # external spot settles T+2 on the joint calendar
MIN_FX_DEAL_USD = 10_000             # smaller nets stay in the position (inside the tolerance)
SWAP_TENOR_MONTHS = 1                # a currency short of cash is funded from USD with a 1-month swap
FX_SWAP_ROUNDING = 100_000
FX_BANK = "BKA"                      # TRS deals external FX with its main bank
# Market quoting order: the first currency of a pair is the base (EUR/USD, GBP/USD, USD/CHF, GBP/CHF)
FX_PAIR_PRIORITY = ["EUR", "GBP", "USD", "CHF"]
